{
  "content": "import sys\n\ndef solve():\n    data = sys.stdin.read().strip().split()\n    if not data:\n        return\n    it = iter(data)\n    n = int(next(it))\n    m = int(next(it))\n    k = int(next(it))\n    a = [int(next(it)) for _ in range(n)]\n    bonus = [[0] * n for _ in range(n)]\n    for _ in range(k):\n        x = int(next(it)) - 1\n        y = int(next(it)) - 1\n        c = int(next(it))\n        bonus[x][y] = c\n    full_mask = (1 << n) - 1\n    dp = [[-10**18] * n for _ in range(1 << n)]\n    for i in range(n):\n        dp[1 << i][i] = a[i]\n    for mask in range(1 << n):\n        for last in range(n):\n            if dp[mask][last] < 0:  # unreachable\n                continue\n            if mask == full_mask:\n                continue\n            for nxt in range(n):\n                if mask & (1 << nxt):\n                    continue\n                new_mask = mask | (1 << nxt)\n                val = dp[mask][last] + a[nxt] + bonus[last][nxt]\n                if val > dp[new_mask][nxt]:\n                    dp[new_mask][nxt] = val\n    ans = -10**18\n    for last in range(n):\n        ans = max(ans, dp[full_mask][last])\n    print(ans)\n\nif __name__ == \"__main__\":\n    solve()\n"
}
